<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use App\Models\PricingVersion;use App\Models\Quotation;use App\Services\QuotationCalculator;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class CompanyQuotationController extends Controller{public function index(Request $request):JsonResponse{$company=$this->company($request,false);return response()->json(['data'=>Quotation::where('company_id',$company->id)->latest()->limit(10)->get()]);}public function store(Request $request,QuotationCalculator $calculator):JsonResponse{$company=$this->company($request,true);$answers=$request->validate(['vacancies'=>['required','integer','min:1','max:25'],'duration'=>['required',Rule::in([7,15,30,60])],'applications'=>['required',Rule::in(['20','50','100','200','unlimited'])],'urgency'=>['required',Rule::in(['normal','15_days','urgent','immediate'])],'visibility'=>['required',Rule::in(['normal','results','home','priority','campaign'])],'classification'=>['required',Rule::in(['manual','filters','assisted','advanced'])],'diffusion'=>['present','array'],'diffusion.*'=>[Rule::in(['platform','email','push','social','sponsored'])],'budget'=>['nullable','integer','min:0']]);$pricing=PricingVersion::where('is_active',true)->latest('version')->firstOrFail();$amounts=$calculator->calculate($answers,$pricing);$quote=Quotation::create(['company_id'=>$company->id,'created_by'=>$request->user()->id,'pricing_version_id'=>$pricing->id,'reference'=>(string)Str::uuid(),'answers'=>$answers,...$amounts,'currency'=>'DOP','expires_at'=>now()->addDays(7)]);return response()->json(['data'=>$quote,'meta'=>['pricing_name'=>$pricing->name,'provisional'=>true,'budget_exceeded'=>filled($answers['budget']??null)&&$amounts['total']>$answers['budget']],'message'=>'Cotización guardada por 7 días.'],201);}private function company(Request $request,bool $write){abort_unless($request->user()->account_type==='company',403);$company=$request->user()->companies()->wherePivot('status','active')->first();abort_unless($company,422,'Completa primero el perfil empresarial.');$role=$company->members()->whereKey($request->user()->id)->first()?->pivot->role;if($write)abort_unless(in_array($role,['owner','admin','recruiter']),403,'Tu rol no permite crear cotizaciones.');return $company;}}
